                assignee?: string;
                /** @description mine, none, or a group slug */
                assignee_group?: string;
                /** @description me or an account uuid: created_by of the node's running run */
                claimer?: string;
                /** @description current (default), all, or a csv of epoch numbers; group_by=epoch defaults to all */
                epoch?: string;
                /** @description RFC 3339, inclusive, on time_field */
                from?: string;
                /** @description csv of graph ids, at most 50 (more is 422) */
                graph_id?: string;
                /** @description csv ≤ 2: status, type, graph_id, epoch, assignee, assignee_group, verdict, data.<path>, created:day|week|month, updated:day|week|month */
                group_by?: string;
                /** @description the current epoch's latest succeeded run has a non-null value for this output */
                has_output?: string;
                /** @description 1: include archived nodes (archived graphs never) */
                include_archived?: "1";
                /** @description csv of exact node keys */
                key?: string;
                /** @description page size (default 50, max 200; more is 400) */
                limit?: number;
                /** @description the node has a link with this role */
                link_role?: "projection" | "gate" | "reference";
                /** @description the node has a link into this system */
                link_system?: string;
                /** @description rows (or groups) to skip; not with after */
                offset?: number;
                /** @description full-text search (websearch syntax) */
                q?: string;
                /** @description exact runner of the node's running run */
                runner?: string;
                /** @description csv ≤ 3, '-' prefix = desc: created_at, updated_at, key, type, status, not_before, epoch, data.<path>, output.<name>; grouped: count or an aggregate's name. id DESC is always last */
                sort?: string;
                /** @description csv of node statuses: active, pending, ready, running, verifying, blocked, done, failed, cancelled */
                status?: string;
                /** @description field from/to bound (default updated_at) */
                time_field?: "created_at" | "updated_at" | "not_before";
                /** @description RFC 3339, exclusive, on time_field */
                to?: string;
                /** @description csv of exact node types */
                type?: string;
                /** @description IANA time zone for time buckets (default UTC) */
                tz?: string;
                /** @description csv of verified, rejected, unverified, unsupported, skipped, pending, none — the current epoch's latest attempt */
                verdict?: string;
                /** @description 1: not_before is in the future */
                waiting?: "1";
                /** @description JSON array of predicates, ≤ 16, ≤ 4 KiB */
                where?: string;
